import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"十三、常见问题","description":"","frontmatter":{"title":"十三、常见问题"},"headers":[],"relativePath":"ch06/13.md","filePath":"ch06/13.md","lastUpdated":1789497795000}'),r={name:"ch06/13.md"};function a(n,t,s,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="十三、常见问题" tabindex="-1">十三、常见问题 <a class="header-anchor" href="#十三、常见问题" aria-label="Permalink to &quot;十三、常见问题&quot;">​</a></h1><table tabindex="0"><thead><tr><th>症状</th><th>原因与解法</th></tr></thead><tbody><tr><td><code>DataSource</code> 注入不进来</td><td>只引了 <code>spring-boot-starter-web</code>，缺 <code>starter-jdbc</code> 或 <code>starter-data-jpa</code></td></tr><tr><td>启动报 <code>Not a managed type</code></td><td>实体不在主类所在包及其子包下，加 <code>@EntityScan</code></td></tr><tr><td>表不存在 / 启动时报 table not found</td><td>连的是非嵌入式库，<code>ddl-auto</code> 默认为 <code>none</code>；用 Flyway 或手工建表</td></tr><tr><td><code>data.sql</code> 报表不存在</td><td>缺 <code>spring.jpa.defer-datasource-initialization: true</code></td></tr><tr><td>连 MySQL 但 <code>data.sql</code> 没执行</td><td><code>spring.sql.init.mode</code> 默认是 <code>embedded</code>，要改成 <code>always</code></td></tr><tr><td>脚本里 <code>#</code> 注释导致语法错误</td><td>初始化脚本只认 <code>--</code> 和 <code>/* */</code></td></tr><tr><td>列名对不上（如 <code>venue_id</code> 与 <code>venueId</code>）</td><td>JPA 靠 <code>@Column</code> / 命名策略；MyBatis-Plus 开 <code>map-underscore-to-camel-case</code></td></tr><tr><td>接口慢但看不到明显问题</td><td>查 Hibernate SQL 日志数条数，大概率是 N+1（第八节）</td></tr><tr><td><code>LazyInitializationException</code></td><td>在事务外访问了 LAZY 关联。要么把取值放事务内，要么改用 DTO 投影</td></tr><tr><td>改了字段没写库</td><td>忘了 <code>@Transactional</code>，或方法被自调用绕过了代理（第七节）</td></tr><tr><td>受检异常不回滚</td><td><code>@Transactional</code> 默认只回滚运行时异常，加 <code>rollbackFor</code> 或转成业务异常</td></tr><tr><td><code>Expecting a SELECT query</code></td><td><code>@Modifying</code> 注解缺失</td></tr><tr><td>批量 UPDATE 后查到旧值</td><td><code>@Modifying</code> 缺 <code>clearAutomatically = true</code></td></tr><tr><td>枚举值莫名变了含义</td><td>用了默认的 <code>EnumType.ORDINAL</code>，改成 <code>STRING</code></td></tr><tr><td>报名通过数可能少算</td><td>用了读-改-写，改成原子 UPDATE（第九节）</td></tr><tr><td>想批量插入但很慢</td><td>主键用了 <code>IDENTITY</code>，Hibernate 无法批量化，换 <code>SEQUENCE</code> 或 UUID</td></tr><tr><td><code>ClassNotFoundException: net.sf.jsqlparser...</code></td><td>MyBatis-Plus 缺 <code>mybatis-plus-jsqlparser</code> 模块</td></tr><tr><td>MyBatis-Plus 分页返回全部数据</td><td>忘了注册 <code>PaginationInnerInterceptor</code>（第 11.5 节，附实测）</td></tr><tr><td>分页第一页少一条 / 最后一页为空</td><td>页码起点搞混：Spring Data 从 0，MyBatis-Plus 从 1</td></tr><tr><td>启动报找不到自动配置类</td><td>MyBatis-Plus starter 用错了版本后缀（<code>spring-boot3</code> 与 <code>spring-boot4</code>）</td></tr></tbody></table><blockquote><p><strong>下一篇要做什么</strong></p><p>数据落盘了，接口也稳了。第 7 篇处理“性能与外部依赖”这一层：用 <code>@Cacheable</code> 把热点查询挡在数据库前面（含缓存穿透、雪崩的应对），用 <code>RestClient</code> 稳定地调用第三方接口（超时、重试、异常映射），以及参数校验的进阶用法、邮件发送和定时任务。</p></blockquote>',3)])])}const b=d(r,[["render",a]]);export{_ as __pageData,b as default};
